def test_percentage_discount():
    def ten_percent_off(total):
        return total * 0.1
    assert checkout(200, ten_percent_off) == 180, 'a 10% discount on 200 must leave 180'

def test_flat_discount():
    def flat_20_off(total):
        return 20
    assert checkout(50, flat_20_off) == 30, 'a flat 20 discount on 50 must leave 30'

def test_discount_never_goes_negative():
    def flat_100_off(total):
        return 100
    assert checkout(30, flat_100_off) == 0, 'a discount larger than the total must clamp the result at 0, never negative'

